#include "sine_control.h"

#include <string.h>

#include "app.c"

static float maximum_profile_amplitude;
static float last_profile_amplitude;

static void record_profile_callback(sine_control_state_t *state,
                                    float frequency_hz,
                                    float amplitude,
                                    int cmock_num_calls)
{
    (void)state;
    (void)frequency_hz;
    (void)cmock_num_calls;

    last_profile_amplitude = amplitude;
    if (amplitude > maximum_profile_amplitude) {
        maximum_profile_amplitude = amplitude;
    }
}

void setUp(void)
{
    maximum_profile_amplitude = -1.0F;
    last_profile_amplitude = -1.0F;
}

void tearDown(void)
{
}

void test_FR_008_01(void)
{
    sine_control_state_t state;
    uint32_t elapsed_ms;

    memset(&state, 0, sizeof(state));
    sine_control_set_profile_StubWithCallback(record_profile_callback);

    for (elapsed_ms = 8000U; elapsed_ms <= 18000U; elapsed_ms += 10U) {
        app_set_profile(&state, elapsed_ms);
    }

    TEST_ASSERT_TRUE(maximum_profile_amplitude <= 0.20F);
}

void test_FR_008_02(void)
{
    sine_control_state_t state;

    memset(&state, 0, sizeof(state));
    state.amplitude = 0.21F;
    sine_control_set_profile_StubWithCallback(record_profile_callback);

    app_set_profile(&state, 10000U);

    TEST_ASSERT_TRUE(last_profile_amplitude < 0.20F);
}
